export const HISTORY_STORAGE_KEY="incredible-india-voice-history";export const MAX_TURNS=200;function memoryStorage(){const t=new Map;return{getItem:e=>t.has(e)?t.get(e):null,setItem:(e,r)=>t.set(e,r)}}function safeLocalStorage(){try{return"undefined"==typeof localStorage?null:localStorage}catch{return null}}export class VoiceConversationHistory{constructor(t={}){this.storage=t.storage||safeLocalStorage()||memoryStorage()}_read(){try{const t=this.storage.getItem(HISTORY_STORAGE_KEY),e=t?JSON.parse(t):[];return Array.isArray(e)?e:[]}catch{return[]}}_write(t){const e=t.slice(-200);return this.storage.setItem(HISTORY_STORAGE_KEY,JSON.stringify(e)),e}append(t){const e={timestamp:Date.now(),viaVoice:!1,...t},r=this._read();return r.push(e),this._write(r)}getTurns(){return this._read()}clear(){return this._write([])}}export default VoiceConversationHistory;